<?php require __DIR__.'/includes/functions.php';require __DIR__.'/includes/data.php';$slug=$_GET['slug']??'';$d=null;$pdo=db();if($pdo){try{$st=$pdo->prepare("SELECT * FROM destinations WHERE slug=? AND status='published' LIMIT 1");$st->execute([$slug]);$d=$st->fetch();}catch(Throwable $e){}}if(!$d){foreach(destinations() as $x){if($x['slug']===$slug){$d=['name'=>$x['name'],'summary'=>$x['text'],'body'=>'','meta_title'=>'','meta_description'=>''];break;}}}if(!$d){http_response_code(404);$d=['name'=>'Destination not found','summary'=>'The requested destination is not available.','body'=>'','meta_title'=>'','meta_description'=>''];}$title=$d['name'];$desc=$d['meta_description']?:$d['summary'];$pageMeta=meta($d['meta_title']?:$title,$desc);require __DIR__.'/includes/header.php';?>
<main><section class="inner-hero"><div class="wrap"><nav class="crumb"><a href="/">Home</a> / <a href="/destinations">Destinations</a> / <?=e($title)?></nav><span class="eyebrow">Tanzania Destination</span><h1><?=e($title)?></h1><p><?=e($d['summary'])?></p></div></section><section class="section wrap"><div class="content-layout"><article class="prose"><?php if(!empty($d['body'])):?><?=$d['body']?><?php else:?><h2>About <?=e($title)?></h2><p><?=e($d['summary'])?></p><p>Use this destination as part of a wider Tanzania itinerary. Route timing, seasonality and travel style should be confirmed for your exact dates.</p><?php endif;?><h2>Plan a trip including <?=e($title)?></h2><p>Tanzania Wildlife Epic can combine this destination with other suitable stops based on your available time and travel priorities.</p><a class="btn gold" href="/contact?destination=<?=urlencode($title)?>">Plan My Trip</a></article><aside class="sticky-enquiry"><h2>Ask About <?=e($title)?></h2><p>Tell us your dates and group size.</p><a class="btn dark" href="/contact">Send Enquiry</a><a class="wa-link" target="_blank" rel="noopener" href="<?=e(wa_link('Hello Tanzania Wildlife Epic, I would like to include '.$title.' in my Tanzania trip.'))?>">Chat on WhatsApp</a></aside></div></section></main><?php require __DIR__.'/includes/footer.php';?>
